mapper.select:
select id, conversation_id as conversationId, sender_id as senderId, msg_type as msgType,
       status, check_status as checkStatus
  from im_message where id = #{id}

select id, guild_kind as guildKind, guild_id as guildId, mentionable, status
  from im_guild_role
 where id in #{i}

select distinct rm.member_id
  from im_guild_role_member rm join im_guild_role r on r.id = rm.role_id and r.status = 1
 where rm.role_id in #{i}

select member_id from im_conversation_member
 where conversation_id = #{conversationId} and deleted = 0
   and member_id in #{i}

select message_id as messageId, reply_to_id as replyToId, thread_root_id as threadRootId
  from im_message_ref
 where message_id in #{i}

select r.thread_root_id as rootId, count(*) as replyCount, max(r.message_id) as lastReplyId
  from im_message_ref r join im_message m on m.id = r.message_id and m.status = 0 and m.check_status = 1
 where r.conversation_id = #{conversationId}
   and r.thread_root_id in #{i}
 group by r.thread_root_id

select r.message_id
  from im_message_ref r join im_message m on m.id = r.message_id and m.status = 0 and m.check_status = 1
 where r.conversation_id = #{conversationId} and r.thread_root_id = #{rootId} and r.message_id > #{after}
 order by r.message_id asc
 limit #{limit}
